Source code in <code>src/jupygrader/notebook_operations.py</code> <pre><code>def remove_code_cells_that_contain(
    nb: NotebookNode, search_str: Union[str, List[str]]
) -&gt; NotebookNode:
    if isinstance(search_str, str):
        search_list = [search_str]
    else:
        search_list = search_str

    nb.cells = [
        cell
        for cell in nb.cells
        if not (cell.cell_type == "code" and any(s in cell.source for s in search_list))
    ]
    return nb
</code></pre>
